def transform(grid):
    from collections import Counter
    # Find background color
    cells = [c for row in grid for c in row]
    bg = Counter(cells).most_common(1)[0][0]

    # Collect non-background colors and pixels
    non_bg_pixels = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != bg:
                non_bg_pixels.append((r, c, grid[r][c]))

    if not non_bg_pixels:
        return [[bg] * 5 for _ in range(5)]

    # Find the most frequent non-background color (for corners)
    freq = Counter(c for _, _, c in non_bg_pixels)
    corner_color = max(freq.keys(), key=k: freq[k])

    # Get unique non-bg colors sorted by first appearance (row-col)
    seen_colors = set()
    color_order = []
    for r, c, col in non_bg_pixels:
        if col not in seen_colors:
            color_order.append(col)
            seen_colors.add(col)
    color_order.sort(key=lambda c: (min(r for r, _, c in non_bg_pixels if c == c), 
                                   min(c for _, c, c in non_bg_pixels if c == c)))

    n = len(color_order)

    # Output size
    if n == 5 or n < 5:
        rows, cols = 5, 5
    else:
        rows, cols = max(5, n + 1), max(5, n + 1)

    output = [[bg] * cols for _ in range(rows)]

    # Corners
    output[0][0] = output[0][cols-1] = output[rows-1][0] = output[rows-1][cols-1] = corner_color

    # Top row (excluding corners)
    for i in range(1, cols-1):
        if i < n:
            output[0][i] = color_order[i-1]

    # Left column (excluding corners)
    for i in range(1, rows-1):
        if i < n:
            output[i][0] = color_order[i-1]

    # Right column (excluding corners)
    for i in range(1, rows-1):
        if i < n:
            output[i][cols-1] = color_order[i-1]

    # Bottom row (excluding corners)
    for i in range(1, cols-1):
        if cols-2-i < n:
            output[rows-1][i] = color_order[n-2-i]

    return output
